svg.script:
(function () {
  var state = {nA:0, xA:0, nB:0, xB:0, sig:false};
  var barA = document.getElementById('barA'), barB = document.getElementById('barB');
  var valA = document.getElementById('valA'), valB = document.getElementById('valB');
  var pval = document.getElementById('pval'), btnLabel = document.getElementById('btnLabel');
  var btn = document.getElementById('btn');

  function normcdf(x) {
    var t = 1 / (1 + 0.2316419 * Math.abs(x));
    var d = 0.3989422804014327 * Math.exp(-x*x/2);
    var p = d * t * (0.319381530 + t * (-0.356563782 + t * (1.781477937 + t * (-1.821255978 + t * 1.330274429))));
    return x > 0 ? 1 - p : p;
  }

  function update() {
    var nA = state.nA, nB = state.nB, xA = state.xA, xB = state.xB;
    var pA = nA ? xA/nA : 0, pB = nB ? xB/nB : 0;
    var p = 1;
    if (nA + nB > 0) {
      var pp = (xA + xB) / (nA + nB);
      var se = Math.sqrt(pp * (1 - pp) * (1/nA + 1/nB));
      if (se > 0) {
        var z = (pA - pB) / se;
        p = 2 * (1 - normcdf(Math.abs(z)));
      }
    }
    p = Math.max(0, Math.min(1, p));
    barA.setAttribute('width', Math.round(pA / 0.4 * 320));
    barB.setAttribute('width', Math.round(pB / 0.4 * 320));
    valA.textContent = (pA * 100).toFixed(1) + '%';
    valB.textContent = (pB * 100).toFixed(1) + '%';
    if (p < 0.05) {
      pval.textContent = '< 0.05';
      pval.setAttribute('fill', '#00ff9c');
      if (!state.sig) {
        state.sig = true;
        btnLabel.textContent = 'RESET';
      }
    } else {
      pval.textContent = p.toFixed(3);
      pval.setAttribute('fill', '#f4f4f5');
    }
    var n = document.getElementById('status');
    n.textContent = 'p = ' + (p < 0.05 ? '< 0.05' : p.toFixed(3)) + ' · n = ' + Math.round(nA) + ' / arm';
  }

  function collect() {
    if (state.sig) { reset(); return; }
    for (var i = 0; i < 150; i++) { if (Math.random() < 0.34) state.xA++; }
    for (var j = 0; j < 150; j++) { if (Math.random() < 0.30) state.xB++; }
    state.nA += 150; state.nB += 150;
    update();
  }

  function reset() {
    state = {nA:0, xA:0, nB:0, xB:0, sig:false};
    btnLabel.textContent = 'COLLECT DATA';
    update();
  }

  document.addEventListener('click', collect);
  document.addEventListener('keydown', function (e) {
    if (e.key === ' ' || e.key === 'Enter') collect();
  });

  update();
})();
